//! Embedded columns end to end: `GENERATED BY EMBEDDING` DDL through a
//! gateway, the worker's `ai_embed` job filling the column from the change
//! feed and backfilling existing rows, `SHOW CREATE TABLE`, the DDL rules
//! and errors, a nearest-neighbour query over the column, re-embedding on
//! a model or source change, and (with `SPRIG_TEST_EMB_KILL`) a kill -9 of
//! the worker in the middle of a batch.
//!
//! Every vector is checked against the bundled model run here, so a row
//! holds exactly the embedding of its current source.
//!
//! ```sh
//! export SPRIG_TEST_EMB_SQL=127.0.0.1:41306      # a gateway (MariaDB or MySQL port)
//! export SPRIG_TEST_EMB_TENANT=acme              # its tenant, user app
//! export SPRIG_EMBED_MODEL_DIR=target/models/bge-small-en-v1.5
//! # optional: kills the worker (kill -9) and starts it again
//! export SPRIG_TEST_EMB_KILL='kill -9 $(cat .../worker.pid); .../start-worker.sh'
//! # optional: the worker's metrics, http://127.0.0.1:41185/metrics
//! export SPRIG_TEST_EMB_METRICS=http://127.0.0.1:41185/metrics
//! # optional: a second alias of the bundled model in ai.embedding_models
//! export SPRIG_TEST_EMB_ALIAS2=local:bge-small-v2
//! cargo test -p sprig-gateway --test embedded_columns_live -- --nocapture
//! ```

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    missing_docs,
    clippy::too_many_lines,
    clippy::cast_precision_loss
)]

use std::time::{Duration, Instant};

use mysql_async::prelude::Queryable;

const DB: &str = "embcol_live";

struct Checks {
    n: usize,
    failed: Vec<String>,
}

impl Checks {
    fn ok(&mut self, what: &str, cond: bool, detail: impl FnOnce() -> String) {
        self.n += 1;
        if cond {
            eprintln!("ok   {what}");
        } else {
            let d = detail();
            eprintln!("FAIL {what}: {d}");
            self.failed.push(format!("{what}: {d}"));
        }
    }
}

async fn sql(addr: &str) -> mysql_async::Conn {
    let tenant = std::env::var("SPRIG_TEST_EMB_TENANT").unwrap_or_else(|_| "acme".into());
    let (host, port) = addr.split_once(':').unwrap();
    let opts = mysql_async::OptsBuilder::default()
        .ip_or_hostname(host)
        .tcp_port(port.parse().unwrap())
        .user(Some(format!("{tenant}.app")))
        .pass(Some("sprig-dev-app"))
        .prefer_socket(false)
        .ssl_opts(mysql_async::SslOpts::default().with_danger_accept_invalid_certs(true));
    mysql_async::Conn::new(opts).await.unwrap()
}

async fn run(c: &mut mysql_async::Conn, s: &str) -> Result<(), String> {
    c.query_drop(s).await.map_err(|e| e.to_string())
}

async fn must(c: &mut mysql_async::Conn, s: &str) {
    if let Err(e) = run(c, s).await {
        panic!("{s}: {e}");
    }
}

async fn count(c: &mut mysql_async::Conn, s: &str) -> u64 {
    c.query_first::<u64, _>(s).await.unwrap().unwrap_or(0)
}

/// Waits until `s` (a count) reaches `want`; the time it took.
async fn wait_count(
    c: &mut mysql_async::Conn,
    s: &str,
    want: u64,
    limit: Duration,
) -> Option<Duration> {
    let t = Instant::now();
    while t.elapsed() < limit {
        if count(c, s).await == want {
            return Some(t.elapsed());
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    None
}

fn parse_vec(s: &str) -> Vec<f32> {
    s.trim_matches(|c| c == '[' || c == ']')
        .split(',')
        .filter(|x| !x.trim().is_empty())
        .map(|x| x.trim().parse().unwrap())
        .collect()
}

fn cos(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b).map(|(x, y)| x * y).sum()
}

/// Every row of `table` whose vector isn't the model's embedding of its
/// `src` (an SQL expression), as (id, cosine); `NULL` vectors must have a
/// blank source.
async fn wrong_rows(
    c: &mut mysql_async::Conn,
    model: &sprig_embed::Embedder,
    table: &str,
    src: &str,
) -> Vec<(i64, f32)> {
    let rows: Vec<(i64, Option<String>, Option<String>)> = c
        .query(format!(
            "SELECT id, {src}, VEC_ToText(embedding) FROM {table} ORDER BY id"
        ))
        .await
        .unwrap();
    let mut wrong = Vec::new();
    let texts: Vec<(i64, String, Vec<f32>)> = rows
        .into_iter()
        .filter_map(|(id, s, v)| match (s, v) {
            (Some(s), Some(v)) if !s.trim().is_empty() => Some((id, s, parse_vec(&v))),
            (s, None) if s.as_deref().is_none_or(|s| s.trim().is_empty()) => None,
            (_, _) => {
                wrong.push((id, -1.0));
                None
            }
        })
        .collect();
    for chunk in texts.chunks(64) {
        let refs: Vec<&str> = chunk.iter().map(|(_, s, _)| s.as_str()).collect();
        let want = model.embed_passages(&refs).unwrap();
        for ((id, _, got), w) in chunk.iter().zip(want) {
            let c = cos(got, &w);
            if c < 0.9999 {
                wrong.push((*id, c));
            }
        }
    }
    wrong
}

async fn metric(url: &str, result: &str) -> u64 {
    let Ok(out) = std::process::Command::new("curl")
        .args(["-fsS", "--max-time", "5", url])
        .output()
    else {
        return 0;
    };
    let text = String::from_utf8_lossy(&out.stdout);
    text.lines()
        .filter(|l| {
            l.starts_with("sprig_ai_embedding_rows_total")
                && l.contains(&format!("result=\"{result}\""))
        })
        .filter_map(|l| l.rsplit(' ').next()?.parse::<f64>().ok())
        .map(|v| v as u64)
        .sum()
}

const WORDS: &[&str] = &[
    "red running shoes for road races",
    "blue trail sneakers with grippy soles",
    "chocolate cake recipe with dark cocoa",
    "vanilla sponge cake for birthdays",
    "waterproof hiking jacket with hood",
    "warm wool socks for winter",
    "espresso machine with milk frother",
    "stainless steel kitchen knife set",
];

fn text(i: usize) -> String {
    format!("{} number {i}", WORDS[i % WORDS.len()])
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn embedded_columns_end_to_end() {
    let Ok(addr) = std::env::var("SPRIG_TEST_EMB_SQL") else {
        eprintln!("skipped: set SPRIG_TEST_EMB_SQL");
        return;
    };
    let dir = std::env::var("SPRIG_EMBED_MODEL_DIR").expect("SPRIG_EMBED_MODEL_DIR");
    let model = sprig_embed::Embedder::load(std::path::Path::new(&dir)).unwrap();
    let metrics = std::env::var("SPRIG_TEST_EMB_METRICS").ok();
    let mut ck = Checks {
        n: 0,
        failed: Vec::new(),
    };
    let mut c = sql(&addr).await;
    must(&mut c, &format!("DROP DATABASE IF EXISTS {DB}")).await;
    must(&mut c, &format!("CREATE DATABASE {DB}")).await;
    must(&mut c, &format!("USE {DB}")).await;

    // ---- backfill of existing rows --------------------------------------
    must(
        &mut c,
        "CREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(200), body TEXT, price INT)",
    )
    .await;
    let n_pre = 300usize;
    let values: Vec<String> = (0..n_pre)
        .map(|i| format!("({i}, 'item {i}', '{}', {i})", text(i)))
        .collect();
    must(
        &mut c,
        &format!("INSERT INTO products VALUES {}", values.join(", ")),
    )
    .await;
    let t = Instant::now();
    must(
        &mut c,
        "ALTER TABLE products ADD COLUMN embedding VECTOR(384) \
         GENERATED BY EMBEDDING(CONCAT_WS(' ', name, body)) USING MODEL 'local:bge-small'",
    )
    .await;
    eprintln!("ALTER ... ADD COLUMN took {} ms", t.elapsed().as_millis());
    let filled = wait_count(
        &mut c,
        "SELECT COUNT(*) FROM products WHERE embedding IS NOT NULL",
        n_pre as u64,
        Duration::from_secs(180),
    )
    .await;
    ck.ok(
        &format!("backfill: {n_pre} existing rows embedded"),
        filled.is_some(),
        || "timed out".into(),
    );
    if let Some(d) = filled {
        eprintln!(
            "     backfill of {n_pre} rows: {:.1} s ({:.0} rows/s)",
            d.as_secs_f64(),
            n_pre as f64 / d.as_secs_f64()
        );
    }
    let wrong = wrong_rows(&mut c, &model, "products", "CONCAT_WS(' ', name, body)").await;
    ck.ok(
        "backfilled vectors are the model's",
        wrong.is_empty(),
        || format!("{wrong:?}"),
    );

    // ---- SHOW CREATE TABLE, hidden columns ------------------------------
    let (_, create): (String, String) = c
        .query_first("SHOW CREATE TABLE products")
        .await
        .unwrap()
        .unwrap();
    ck.ok(
        "SHOW CREATE TABLE prints the clause",
        create.contains(
            "GENERATED BY EMBEDDING(concat_ws(' ',`name`,`body`)) USING MODEL 'local:bge-small'",
        ),
        || create.clone(),
    );
    ck.ok(
        "SHOW CREATE TABLE hides the hidden columns",
        !create.contains("_sprig_"),
        || create.clone(),
    );
    let cols: Vec<String> = c
        .query(format!(
            "SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = '{DB}' \
             AND TABLE_NAME = 'products' ORDER BY ORDINAL_POSITION"
        ))
        .await
        .unwrap();
    ck.ok(
        "information_schema shows the column, not the hidden ones",
        cols == ["id", "name", "body", "price", "embedding"],
        || format!("{cols:?}"),
    );
    let e = run(&mut c, "SELECT _sprig_emb_embedding_hash FROM products").await;
    ck.ok(
        "a hidden column can't be read",
        e.as_ref().is_err_and(|e| e.contains("1054")),
        || format!("{e:?}"),
    );

    // ---- inserts, updates, deletes --------------------------------------
    let t = Instant::now();
    let values: Vec<String> = (1000..1020)
        .map(|i| format!("({i}, 'new {i}', '{}', 1)", text(i)))
        .collect();
    must(
        &mut c,
        &format!(
            "INSERT INTO products (id, name, body, price) VALUES {}",
            values.join(", ")
        ),
    )
    .await;
    let d = wait_count(
        &mut c,
        "SELECT COUNT(*) FROM products WHERE id >= 1000 AND embedding IS NOT NULL",
        20,
        Duration::from_secs(60),
    )
    .await;
    ck.ok("inserted rows are filled", d.is_some(), || {
        "timed out".into()
    });
    if d.is_some() {
        eprintln!(
            "     insert to vector: {} ms for 20 rows",
            t.elapsed().as_millis()
        );
    }
    let before: String = c
        .query_first("SELECT VEC_ToText(embedding) FROM products WHERE id = 1000")
        .await
        .unwrap()
        .unwrap();
    must(
        &mut c,
        "UPDATE products SET body = 'a cast iron frying pan' WHERE id = 1000",
    )
    .await;
    // A change to another column leaves the vector alone.
    must(&mut c, "UPDATE products SET price = 99 WHERE id = 1001").await;
    let t = Instant::now();
    let mut changed = false;
    while t.elapsed() < Duration::from_secs(60) {
        let now: String = c
            .query_first("SELECT VEC_ToText(embedding) FROM products WHERE id = 1000")
            .await
            .unwrap()
            .unwrap_or_default();
        if now != before && !now.is_empty() {
            changed = true;
            break;
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    ck.ok("an updated source is embedded again", changed, || {
        "the vector didn't change".into()
    });
    must(
        &mut c,
        "UPDATE products SET name = NULL, body = '   ' WHERE id = 1002",
    )
    .await;
    let cleared = wait_count(
        &mut c,
        "SELECT COUNT(*) FROM products WHERE id = 1002 AND embedding IS NULL",
        1,
        Duration::from_secs(60),
    )
    .await;
    ck.ok(
        "a blank source clears the vector",
        cleared.is_some(),
        || "still set".into(),
    );
    must(&mut c, "DELETE FROM products WHERE id = 1003").await;
    let wrong = wrong_rows(&mut c, &model, "products", "CONCAT_WS(' ', name, body)").await;
    ck.ok(
        "after inserts, updates and deletes every vector is its row's",
        wrong.is_empty(),
        || format!("{wrong:?}"),
    );

    // ---- nearest neighbours over the column -----------------------------
    let q = model
        .embed_query("shoes for running")
        .unwrap()
        .iter()
        .map(f32::to_string)
        .collect::<Vec<_>>()
        .join(",");
    let ids: Vec<(i64, String)> = c
        .query(format!(
            "SELECT id, body FROM products WHERE embedding IS NOT NULL \
             ORDER BY VEC_DISTANCE_COSINE(embedding, VEC_FromText('[{q}]')) LIMIT 5"
        ))
        .await
        .unwrap();
    ck.ok(
        "ORDER BY VEC_DISTANCE_COSINE finds the running shoes",
        ids.iter()
            .all(|(_, b)| b.contains("running shoes") || b.contains("sneakers")),
        || format!("{ids:?}"),
    );

    // ---- DDL rules and errors -------------------------------------------
    for (stmt, want) in [
        (
            "ALTER TABLE products ADD COLUMN e2 VECTOR(100) GENERATED BY EMBEDDING(body) USING MODEL 'local:bge-small'",
            "39997",
        ),
        (
            "ALTER TABLE products ADD COLUMN e2 VECTOR(384) GENERATED BY EMBEDDING(body) USING MODEL 'no-such-model'",
            "39997",
        ),
        (
            "ALTER TABLE products ADD COLUMN e2 VECTOR(384) GENERATED BY EMBEDDING(body) USING MODEL 'local:bge-small' ON CHANGE SYNC",
            "39997",
        ),
        (
            "ALTER TABLE products ADD COLUMN e2 VECTOR(384) GENERATED BY EMBEDDING(RAND()) USING MODEL 'local:bge-small'",
            "39997",
        ),
        (
            "ALTER TABLE products MODIFY embedding VECTOR(384) NULL",
            "39997",
        ),
        (
            "ALTER TABLE products RENAME COLUMN embedding TO e3",
            "39997",
        ),
        (
            "ALTER TABLE products CHANGE embedding e3 VECTOR(384)",
            "39997",
        ),
        ("ALTER TABLE products DROP COLUMN body", "1054"),
        (
            "ALTER TABLE products ADD COLUMN _sprig_x INT, ADD COLUMN e2 VECTOR(384) GENERATED BY EMBEDDING(body) USING MODEL 'local:bge-small'",
            "39050",
        ),
        (
            "CREATE TABLE nopk (a INT, e VECTOR(384) GENERATED BY EMBEDDING(a) USING MODEL 'local:bge-small')",
            "39997",
        ),
    ] {
        let r = run(&mut c, stmt).await;
        ck.ok(
            &format!("refused: {stmt}"),
            r.as_ref().is_err_and(|e| e.contains(want)),
            || format!("{r:?}"),
        );
    }

    // ---- CREATE TABLE with the clause, DROP COLUMN ------------------------
    must(
        &mut c,
        "CREATE TABLE notes (id BIGINT PRIMARY KEY, body TEXT, \
         e VECTOR(384) GENERATED BY EMBEDDING(body) USING MODEL 'local:bge-small' WITH (max_input_tokens = 16))",
    )
    .await;
    let long = "word ".repeat(400);
    must(
        &mut c,
        &format!("INSERT INTO notes (id, body) VALUES (1, 'short note'), (2, '{long}')"),
    )
    .await;
    let d = wait_count(
        &mut c,
        "SELECT COUNT(*) FROM notes WHERE e IS NOT NULL",
        2,
        Duration::from_secs(60),
    )
    .await;
    ck.ok(
        "CREATE TABLE ... GENERATED BY EMBEDDING fills",
        d.is_some(),
        || "timed out".into(),
    );
    let got: Option<String> = c
        .query_first("SELECT VEC_ToText(e) FROM notes WHERE id = 2")
        .await
        .unwrap();
    let want = model
        .embed_passages_truncated(&[long.as_str()], 16)
        .unwrap();
    ck.ok(
        "max_input_tokens cuts the input",
        got.as_deref()
            .is_some_and(|g| cos(&parse_vec(g), &want[0]) > 0.9999),
        || format!("{got:?}"),
    );
    must(&mut c, "ALTER TABLE notes DROP COLUMN e").await;
    let (_, create): (String, String) = c
        .query_first("SHOW CREATE TABLE notes")
        .await
        .unwrap()
        .unwrap();
    ck.ok(
        "DROP COLUMN takes the hidden columns",
        !create.contains("EMBEDDING") && !create.contains(" `e` "),
        || create.clone(),
    );
    must(&mut c, "SET @sprig_show_internal = 1").await;
    let (_, create): (String, String) = c
        .query_first("SHOW CREATE TABLE notes")
        .await
        .unwrap()
        .unwrap();
    must(&mut c, "SET @sprig_show_internal = 0").await;
    ck.ok(
        "no hidden column is left behind",
        !create.contains("_sprig_emb_"),
        || create.clone(),
    );
    // Added again: a new column, filled again.
    must(
        &mut c,
        "ALTER TABLE notes ADD COLUMN e VECTOR(384) GENERATED BY EMBEDDING(body) USING MODEL 'local:bge-small'",
    )
    .await;
    let d = wait_count(
        &mut c,
        "SELECT COUNT(*) FROM notes WHERE e IS NOT NULL",
        2,
        Duration::from_secs(60),
    )
    .await;
    ck.ok("dropped and added again: filled again", d.is_some(), || {
        "timed out".into()
    });

    // ---- kill -9 of the worker in the middle of a batch -------------------
    if let Ok(kill) = std::env::var("SPRIG_TEST_EMB_KILL") {
        must(
            &mut c,
            "CREATE TABLE burst (id INT PRIMARY KEY, body TEXT, \
             embedding VECTOR(384) GENERATED BY EMBEDDING(body) USING MODEL 'local:bge-small')",
        )
        .await;
        // Let the job start.
        tokio::time::sleep(Duration::from_secs(4)).await;
        let n = 1500usize;
        for part in (0..n).collect::<Vec<_>>().chunks(500) {
            let values: Vec<String> = part
                .iter()
                .map(|&i| format!("({i}, '{}')", text(i)))
                .collect();
            must(
                &mut c,
                &format!("INSERT INTO burst (id, body) VALUES {}", values.join(", ")),
            )
            .await;
        }
        // Mid-way: some rows done, most not.
        let t = Instant::now();
        let mut done_before = 0;
        while t.elapsed() < Duration::from_secs(60) {
            done_before = count(
                &mut c,
                "SELECT COUNT(*) FROM burst WHERE embedding IS NOT NULL",
            )
            .await;
            if done_before >= 100 {
                break;
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
        let embedded_before = match &metrics {
            Some(u) => metric(u, "embedded").await,
            None => 0,
        };
        let out = std::process::Command::new("sh")
            .args(["-c", &kill])
            .output()
            .unwrap();
        eprintln!(
            "     kill -9 with {done_before} of {n} rows done; worker had embedded {embedded_before} rows: {}{}",
            String::from_utf8_lossy(&out.stdout).trim(),
            String::from_utf8_lossy(&out.stderr).trim()
        );
        ck.ok(
            "the worker was killed and started again",
            out.status.success(),
            || format!("{out:?}"),
        );
        let at_kill = count(
            &mut c,
            "SELECT COUNT(*) FROM burst WHERE embedding IS NOT NULL",
        )
        .await;
        // Updates while the worker is down are not lost either.
        must(
            &mut c,
            "UPDATE burst SET body = CONCAT(body, ' (edited)') WHERE id % 100 = 0",
        )
        .await;
        let d = wait_count(
            &mut c,
            "SELECT COUNT(*) FROM burst WHERE embedding IS NOT NULL",
            n as u64,
            Duration::from_secs(300),
        )
        .await;
        ck.ok(
            "after kill -9 every row is filled (no loss)",
            d.is_some(),
            || "timed out".into(),
        );
        // Every vector is its current source's: nothing stale, nothing
        // from an earlier source written over a newer one.
        tokio::time::sleep(Duration::from_secs(3)).await;
        let wrong = wrong_rows(&mut c, &model, "burst", "body").await;
        ck.ok(
            "after kill -9 every vector is its row's current source's",
            wrong.is_empty(),
            || format!("{wrong:?}"),
        );
        if let Some(u) = &metrics {
            let after = metric(u, "embedded").await;
            let skipped = metric(u, "skipped").await;
            // The new process embedded the rows not done at the kill and
            // the 15 edited ones; the ones done before were passed over.
            let left = n as u64 - at_kill + 15;
            eprintln!(
                "     after restart: embedded {after}, skipped {skipped} (rows left at the kill: {}, edits: 15)",
                n as u64 - at_kill
            );
            ck.ok(
                "no row embedded twice for the same source (new process's embeds <= rows left + edits + one batch)",
                after <= left + 64,
                || format!("embedded {after}, left {left}"),
            );
        }
        let rows = count(&mut c, "SELECT COUNT(*) FROM burst").await;
        ck.ok("no duplicate rows", rows == n as u64, || format!("{rows}"));
    }

    // ---- re-embedding on a model or source change ------------------------
    let old: String = c
        .query_first("SELECT VEC_ToText(embedding) FROM products WHERE id = 5")
        .await
        .unwrap()
        .unwrap();
    must(
        &mut c,
        "ALTER TABLE products MODIFY COLUMN embedding VECTOR(384) \
         GENERATED BY EMBEDDING(body) USING MODEL 'local:bge-small'",
    )
    .await;
    let still: String = c
        .query_first("SELECT VEC_ToText(embedding) FROM products WHERE id = 5")
        .await
        .unwrap()
        .unwrap();
    ck.ok(
        "readers see the old vectors until the cutover",
        still == old,
        || "changed at once".into(),
    );
    let r = run(
        &mut c,
        "ALTER TABLE products MODIFY COLUMN embedding VECTOR(384) \
         GENERATED BY EMBEDDING(name) USING MODEL 'local:bge-small'",
    )
    .await;
    ck.ok(
        "a second change waits for the first",
        r.as_ref().is_err_and(|e| e.contains("39997")),
        || format!("{r:?}"),
    );
    let t = Instant::now();
    let mut cut = false;
    while t.elapsed() < Duration::from_secs(240) {
        let (_, create): (String, String) = c
            .query_first("SHOW CREATE TABLE products")
            .await
            .unwrap()
            .unwrap();
        if create.contains("GENERATED BY EMBEDDING(`body`)") {
            cut = true;
            break;
        }
        tokio::time::sleep(Duration::from_millis(250)).await;
    }
    ck.ok("the new source is cut over", cut, || "timed out".into());
    eprintln!(
        "     re-embedding (new source) of {} rows: {:.1} s",
        count(&mut c, "SELECT COUNT(*) FROM products").await,
        t.elapsed().as_secs_f64()
    );
    let wrong = wrong_rows(&mut c, &model, "products", "body").await;
    ck.ok(
        "after the cutover every vector is the new source's",
        wrong.is_empty(),
        || format!("{} wrong, first {:?}", wrong.len(), wrong.first()),
    );
    if let Ok(alias2) = std::env::var("SPRIG_TEST_EMB_ALIAS2") {
        must(
            &mut c,
            &format!(
                "ALTER TABLE products MODIFY COLUMN embedding VECTOR(384) \
                 GENERATED BY EMBEDDING(body) USING MODEL '{alias2}'"
            ),
        )
        .await;
        let t = Instant::now();
        let mut cut = false;
        while t.elapsed() < Duration::from_secs(240) {
            let (_, create): (String, String) = c
                .query_first("SHOW CREATE TABLE products")
                .await
                .unwrap()
                .unwrap();
            if create.contains(&format!("USING MODEL '{alias2}'")) {
                cut = true;
                break;
            }
            tokio::time::sleep(Duration::from_millis(250)).await;
        }
        ck.ok("a model change is cut over", cut, || "timed out".into());
        eprintln!(
            "     re-embedding (new model) : {:.1} s",
            t.elapsed().as_secs_f64()
        );
        let wrong = wrong_rows(&mut c, &model, "products", "body").await;
        ck.ok(
            "after the model change every vector is filled",
            wrong.is_empty(),
            || format!("{wrong:?}"),
        );
    }
    // Writes keep working after the cutovers.
    must(
        &mut c,
        "INSERT INTO products (id, name, body, price) VALUES (5000, 'after', 'a garden hose with a spray nozzle', 1)",
    )
    .await;
    let d = wait_count(
        &mut c,
        "SELECT COUNT(*) FROM products WHERE id = 5000 AND embedding IS NOT NULL",
        1,
        Duration::from_secs(60),
    )
    .await;
    ck.ok(
        "rows written after the cutover are filled",
        d.is_some(),
        || "timed out".into(),
    );

    // ---- DROP TABLE ends the column ---------------------------------------
    must(&mut c, "DROP TABLE notes").await;
    must(&mut c, &format!("DROP DATABASE {DB}")).await;
    eprintln!("{} checks, {} failed", ck.n, ck.failed.len());
    assert!(ck.failed.is_empty(), "{:#?}", ck.failed);
}
